            cpu->pbr = 0xC1u;
            cpu->pc = 0xFA20u;
            if (nh_scpu_expect_next(cpu, 0x060FD100u) != NH_SCPU_EXECUTED)
                return NH_SCPU_STOPPED;
            return nh_scpu_finish(cpu, bus, 8u);
